import re, subprocess, os, collections, json

files = subprocess.check_output(["bash","-c","find . -name '*.go' -not -path './graphify-out/*'"]).decode().split()
src = {}
pkgof = {}
for f in files:
    t = open(f, encoding='utf-8', errors='replace').read()
    src[f] = t
    m = re.search(r'^package (\w+)', t, re.M)
    pkgof[f] = m.group(1) if m else ''

internal_files = [f for f in files if f.startswith('./internal/') and not f.endswith('_test.go')]

decls = []  # (name, recv_type, pkg, file, isMethod)
for f in internal_files:
    for m in re.finditer(r'^func\s+(?:\((\w+)\s+\*?([\w\[\]]+)\)\s+)?([A-Za-z_]\w*)\s*[\(\[]', src[f], re.M):
        decls.append({'name': m.group(3), 'recv': m.group(2), 'pkg': pkgof[f], 'file': f,
                      'method': m.group(2) is not None})

results = []
for d in decls:
    name = d['name']
    cnt = 0
    locs = []
    if d['method']:
        pat = re.compile(r'\.' + re.escape(name) + r'\s*\(')
    else:
        pat = None
    for f in files:
        if f.endswith('_test.go'): continue
        t = src[f]
        lines = t.split('\n')
        for i, ln in enumerate(lines):
            s = ln.split('//')[0]
            if d['method']:
                if pat.search(s):
                    cnt += 1; locs.append(f'{f}:{i+1}')
            else:
                hit = False
                if pkgof[f] == d['pkg'] and f.startswith(os.path.dirname(d['file'])):
                    if re.search(r'(?<![\w.])' + re.escape(name) + r'\s*\(', s) and not s.lstrip().startswith('func '):
                        hit = True
                if re.search(r'(?<![\w.])' + re.escape(d['pkg']) + r'\.' + re.escape(name) + r'\s*\(', s):
                    hit = True
                if hit:
                    cnt += 1; locs.append(f'{f}:{i+1}')
    results.append((cnt, name, d['recv'], d['file'], locs))

results.sort(reverse=True, key=lambda r: r[0])
for r in results[:30]:
    print(r[0], r[1], 'recv=' + str(r[2]), r[3])
json.dump([{'n':r[0],'name':r[1],'recv':r[2],'file':r[3],'locs':r[4][:200]} for r in results[:30]], open('/tmp/fanin.json','w'), indent=1)
EOF
python3 /tmp/fanin.py

